// itxGenDCT32x32C8R8 is the 8-bit 32x32 DCT_DCT inverse transform and add for
// coefficients in the first 8 columns and 8 rows (column-major at stride
// 32); dp/pp address the destination and prediction at strides ds/ps,
// which the caller has bounds-checked. Coefficient rows from rows on are
// zero: the row strips past them are skipped (tmp starts zero). It reports
// false, with dst untouched, when a guard declines.
func itxGenDCT32x32C8R8(c *[1024]int32, dp unsafe.Pointer, ds int, pp unsafe.Pointer, ps int, rows int) bool {
	var tmp [256]int16
	var gc [4]archsimd.Uint16x8
	if !itxGenDCT32Row8((*[232]int32)(c[0:]), (*[256]int16)(tmp[0:]), &gc) {
		return false
	}
	m := gc[0].Max(gc[1]).Max(gc[2]).Max(gc[3])
	if m.ReduceMax() > itx16ColumnL1Bound {
		return false
	}
	sel := &itxGenKp.sel
	itxGenDCT32Col8((*[232]int16)(tmp[0:]), dp, ds, pp, ps, &sel[0])
	itxGenDCT32Col8((*[232]int16)(tmp[8:]), unsafe.Add(dp, 8), ds, unsafe.Add(pp, 0), ps, &sel[1])
	itxGenDCT32Col8((*[232]int16)(tmp[16:]), unsafe.Add(dp, 16), ds, unsafe.Add(pp, 8), ps, &sel[1])
	itxGenDCT32Col8((*[232]int16)(tmp[24:]), unsafe.Add(dp, 24), ds, unsafe.Add(pp, 16), ps, &sel[1])
	return true
}

