	sel := archsimd.LoadUint8x16Array(selp)
	t := itxGenKp
	bias := archsimd.LoadInt32x4Array(&t.bias)
	var zero archsimd.Int16x8
	sh3 := archsimd.LoadInt16x8Array(&t.shr3)
