	k27 := archsimd.LoadInt32x4Array(&t.p401)
	r24l := w25.MulAdd(k27, bias)
	r24h := w26.MulAdd(k27, bias)
	r24 := r24l.ToBits().ReshapeToUint16s().ConcatOdd(r24h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k29 := archsimd.LoadInt32x4Array(&t.p4076)
	r28l := w25.MulAdd(k29, bias)
	r28h := w26.MulAdd(k29, bias)
	r28 := r28l.ToBits().ReshapeToUint16s().ConcatOdd(r28h.ToBits().ReshapeToUint16s()).BitsToInt16()
	w31 := r28.ExtendLo4ToInt32()
	w32 := r28.HiToLo().ExtendLo4ToInt32()
	k33 := archsimd.LoadInt32x4Array(&t.p1567)
	r30l := w31.MulAdd(k33, bias)
	r30h := w32.MulAdd(k33, bias)
	w34 := r24.ExtendLo4ToInt32()
	w35 := r24.HiToLo().ExtendLo4ToInt32()
	k36 := archsimd.LoadInt32x4Array(&t.n3784)
	r30l = w34.MulAdd(k36, r30l)
	r30h = w35.MulAdd(k36, r30h)
	r30 := r30l.ToBits().ReshapeToUint16s().ConcatOdd(r30h.ToBits().ReshapeToUint16s()).BitsToInt16()
	k38 := archsimd.LoadInt32x4Array(&t.p3784)
	r37l := w31.MulAdd(k38, bias)
	r37h := w32.MulAdd(k38, bias)
	k39 := archsimd.LoadInt32x4Array(&t.p1567)
	r37l = w34.MulAdd(k39, r37l)
	r37h = w35.MulAdd(k39, r37h)
	r37 := r37l.ToBits().ReshapeToUint16s().ConcatOdd(r37h.ToBits().ReshapeToUint16s()).BitsToInt16()
	w41 := r37.ExtendLo4ToInt32()
	w42 := r37.HiToLo().ExtendLo4ToInt32()
